def add(id,status,finding,refs,successors,phase=None):
 leaves.append({'id':id,'status':status,'originalRequirement':requirements[id],'finding':finding,'sourceAndTestReferences':refs,'evidence':commonEvidence+([D+'parallel-next100/next100-c'+id[-2:]+'.md'] if id.startswith('A-M') else []),'checksActuallyPerformed':['Read full original leaf and current component/extension contracts','Inspect current source and named unit/native test assertions without executing suites','Reconcile relevant hashes with FA-02 and prior parallel graph; reuse FA-04 passing unaffected unit stages','Resolve scope against accepted F/T/native receipts and current open V leaves'],'phaseEvidence':phase or {},'inputHeadHostLimits':limits,'successors':successors,'newDefectsConfirmed':[]})
