 refs=[S+name+'/'+name+'.tsx',S+name+'/'+name+'.test.tsx',D+contract,W+browser,D+'parallel-next100/next100-c'+str(n)+'.md',D+'backlog-execution-2026-10-15.md',D+'react-aria-migration-inventory-acceptance.md']
 if n in [26,29,34]:refs.append(S+name+'/'+name+'.impl.tsx')
 if n in [24,31,32,33]:refs.append(W+('hardening-actions-presentation.spec.ts' if n==24 else 'hardening-editor-dialogs-presentation.spec.ts'))
 successors=[] if status=='complete' else [todo('W03-C'+str(n)+'-V',gap,'Close V-C'+str(n)+'-04/05 with native engine/version/source/fixture hashes, measured geometry, reviewed screenshots and translated names/order; do not infer spoken AT from DOM labels.')]
 if n in [26,34]:successors.append(todo('W03-C'+str(n)+'-E','Reconcile the missing E-family command/content/IME/trust rows from command-and-trust-matrix.md.','Retain one result per missing row; no duplicate suite or broad parent closure from one fixture.'))
